code.java:
interface Observer { void update(String msg); }
class NewsPublisher {
    private List<Observer> observers = new ArrayList<>();
    public void subscribe(Observer o) { observers.add(o); }
    public void notify(String msg) {
        for (Observer o : observers) o.update(msg);
    }
}

code.cpp:
class Observer { public: virtual void update(std::string msg) = 0; };
class NewsPublisher {
    std::vector<Observer*> observers;
public:
    void subscribe(Observer* o) { observers.push_back(o); }
    void notify(std::string msg) {
        for(auto o : observers) o->update(msg);
    }
};

code.python:
class Observer(ABC):
    @abstractmethod
    def update(self, msg): pass
class NewsPublisher:
    def __init__(self):
        self._observers = []
    def subscribe(self, o): self._observers.append(o)
    def notify(self, msg):
        for o in self._observers: o.update(msg)

code.typescript:
interface Observer { update(msg: string): void; }
class NewsPublisher {
    private observers: Observer[] = [];
    public subscribe(o: Observer) { this.observers.push(o); }
    public notify(msg: string) {
        this.observers.forEach(o => o.update(msg));
    }
}

